 XV. Factual Knowledge Update Mechanizmus

 Dynamikus Tudásbázis Frissítés RetrievalFree

A factual knowledge update problémára  megoldás retrieval nélkül:[3]

zig
const DynamicKnowledgeUpdater = struct {
    knowledge_graph: *SemanticGraph,
    temporal_index: TemporalKnowledgeIndex,
    haar_consolidator: *HaarWaveletMemoryConsolidator,

    pub fn updateFactualKnowledge(
        self: *DynamicKnowledgeUpdater,
        new_facts: []const FactualStatement,
        model: *JaideNeuralV41,
        allocator: std.mem.Allocator,
    ) !UpdateResult {
        // 1. Új tények beágyazása model embedding terébe
        var fact_embeddings = try allocator.alloc([]f32, new_facts.len);
        defer allocator.free(fact_embeddings);

        for (new_facts, 0..) |fact, i| {
            const tokens = try model.mgt_tokenizer.tokenize(
                fact.text,
                allocator
            );
            defer tokens.deinit();

            const embedding = try model.computeFactEmbedding(
                tokens.items,
                allocator
            );
            fact_embeddings[i] = embedding;
        }

        // 2. Temporal indexálás: mikor vált ez a tudás érvényessé
        for (new_facts, 0..) |fact, i| {
            try self.temporal_index.insert(
                fact_embeddings[i],
                fact.timestamp,
                fact.validity_period,
                allocator
            );
        }

        // 3. Konfliktus detektálás meglévő tudással
        var conflicts = std.ArrayList(KnowledgeConflict).init(allocator);
        defer conflicts.deinit();

        for (new_facts, 0..) |new_fact, i| {
            const existing_facts = try self.knowledge_graph.findRelatedFacts(
                fact_embeddings[i],
                0.85, // similarity threshold
                allocator
            );
            defer existing_facts.deinit();

            for (existing_facts.items) |existing| {
                if (self.areConflicting(new_fact, existing)) {
                    try conflicts.append(KnowledgeConflict{
                        .new_fact = new_fact,
                        .old_fact = existing,
                        .conflict_type = try self.detectConflictType(new_fact, existing),
                    });
                }
            }
        }

        // 4. Konfliktusmegoldás temporális precedencia alapján
        for (conflicts.items) |conflict| {
            if (conflict.new_fact.timestamp > conflict.old_fact.timestamp) {
                // Új tény érvényesül: jelöljük elavultnak a régit
                try self.knowledge_graph.markDeprecated(
                    conflict.old_fact.id,
                    conflict.new_fact.timestamp,
                );
            }
        }

        // 5. Haar-wavelet konszolidáció: új tudás beépítése
        const consolidated = try self.haar_consolidator.consolidateKnowledge(
            fact_embeddings,
            &model.previous_tasks_memory,
            allocator
        );

        // 6. Model weight-ek finom hangolása új tudásra
        const finetuned_layers = try self.finetuneWithKnowledge(
            model.rsf_layers,
            fact_embeddings,
            new_facts,
            allocator
        );

        // 7. Knowledge graph frissítése
        for (new_facts, 0..) |fact, i| {
            const concept_node = try self.knowledge_graph.createOrUpdateNode(
                fact_embeddings[i],
                fact.text,
                fact.timestamp,
                allocator
            );

            // Relációk létrehozása
            if (fact.subject_entity) |subj| {
                if (fact.object_entity) |obj| {
                    try self.knowledge_graph.createEdge(
                        subj.concept_id,
                        obj.concept_id,
                        fact.relation_type,
                        fact.timestamp,
                    );
                }
            }
        }

        return UpdateResult{
            .facts_added = new_facts.len,
            .conflicts_resolved = conflicts.items.len,
            .forgetting_ratio = consolidated.forgetting_ratio,
            .updated_knowledge_graph = self.knowledge_graph,
        };
    }

    fn finetuneWithKnowledge(
        self: *DynamicKnowledgeUpdater,
        layers: []RSFLayer,
        fact_embeddings: []const []const f32,
        facts: []const FactualStatement,
        allocator: std.mem.Allocator,
    ) ![]RSFLayer {
        // Low-rank adaptation (LoRA-szerű) frissítés
        var updated_layers = try allocator.alloc(RSFLayer, layers.len);

        for (layers, 0..) |layer, i| {
            updated_layers[i] = layer;

            // Minden fact-ra számítsuk a gradienst
            for (fact_embeddings, 0..) |emb, j| {
                const target_output = try self.parseTargetFromFact(facts[j], allocator);

                // Forward pass
                const output = try layer.forward(emb, allocator);

                // Loss: MSE
                const loss = try self.computeMSE(output, target_output);

                // Backward pass: gradient számítás
                const grad = try layer.backward(emb, output, target_output, allocator);

                // Low-rank update: ΔW = α * u * v^T
                const alpha: f32 = 0.001;
                try updated_layers[i].applyLowRankUpdate(grad, alpha);
            }
        }

        return updated_layers;
    }
};

const TemporalKnowledgeIndex = struct {
    time_bins: std.AutoHashMap(i64, []KnowledgeEntry),

    pub fn insert(
        self: *TemporalKnowledgeIndex,
        embedding: []const f32,
        timestamp: i64,
        validity: ValidityPeriod,
        allocator: std.mem.Allocator,
    ) !void {
        const bin_key = self.timestampToBin(timestamp);

        const entry = KnowledgeEntry{
            .embedding = embedding,
            .timestamp = timestamp,
            .valid_from = validity.start,
            .valid_until = validity.end,
        };

        if (self.time_bins.getPtr(bin_key)) |bin| {
            // Append to existing bin
            var new_bin = try allocator.alloc(KnowledgeEntry, bin.len + 1);
            @memcpy(new_bin[0..bin.len], bin.*);
            new_bin[bin.len] = entry;
            bin.* = new_bin;
        } else {
            // Create new bin
            var new_bin = try allocator.alloc(KnowledgeEntry, 1);
            new_bin[0] = entry;
            try self.time_bins.put(bin_key, new_bin);
        }
    }

    pub fn queryAtTime(
        self: *TemporalKnowledgeIndex,
        query_embedding: []const f32,
        query_time: i64,
        allocator: std.mem.Allocator,
    ) ![]KnowledgeEntry {
        var results = std.ArrayList(KnowledgeEntry).init(allocator);

        // Keressünk minden relevánslás time bin-ben
        var iter = self.time_bins.iterator();
        while (iter.next()) |kv| {
            for (kv.value_ptr.*) |entry| {
                // Időbeli érvényesség check
                if (query_time >= entry.valid_from and query_time <= entry.valid_until) {
                    // Szemantikus hasonlóság
                    const similarity = cosineSimilarity(query_embedding, entry.embedding);

                    if (similarity > 0.8) {
                        try results.append(entry);
                    }
                }
            }
        }

        return results.toOwnedSlice();
    }

    fn timestampToBin(self: *TemporalKnowledgeIndex, timestamp: i64) i64 {
        // Bin size: 1 nap (86400 másodperc)
        const bin_size: i64 = 86400;
        return @divFloor(timestamp, bin_size);
    }
};

const FactualStatement = struct {
