 XVI. Bolyai János És A NemEuklideszi Geometria Inspiráció

 Hiperbolikus Embedding Tér Kompozíciós Generalizációhoz

Bolyai János (18021860) szegedi származású matematikus, a nemeuklideszi geometria egyik megalapítója. A hiperbolikus tér tulajdonságai tökéletesek kompozíciós reprezentációkhoz:

zig
const BolyaiHyperbolicEmbedding = struct {
    poincare_ball_radius: f32,
    curvature: f32,

    pub fn embedInHyperbolicSpace(
        self: *BolyaiHyperbolicEmbedding,
        euclidean_embedding: []const f32,
        allocator: std.mem.Allocator,
    ) ![]f32 {
        // Euklideszi -> Poincaré ball mapping
        var hyperbolic = try allocator.alloc(f32, euclidean_embedding.len);

        const norm = euclideanNorm(euclidean_embedding);
        const scale_factor = @tanh(norm / 2.0);

        for (euclidean_embedding, 0..) |val, i| {
            hyperbolic[i] = (val / norm) * scale_factor;
        }

        return hyperbolic;
    }

    pub fn hyperbolicDistance(
        self: *BolyaiHyperbolicEmbedding,
        x: []const f32,
        y: []const f32,
    ) f32 {
        // Poincaré ball metrikus: d(x,y) = arcosh(1 + 2||x-y||²/((1-||x||²)(1-||y||²)))

        var diff_norm_sq: f32 = 0.0;
        for (x, 0..) |x_i, i| {
            const diff = x_i - y[i];
            diff_norm_sq += diff * diff;
        }

        const x_norm_sq = dotProduct(x, x);
        const y_norm_sq = dotProduct(y, y);

        const numerator = 2.0 * diff_norm_sq;
        const denominator = (1.0 - x_norm_sq) * (1.0 - y_norm_sq);

        if (denominator < 1e-8) {
            return std.math.inf(f32);
        }

        const arg = 1.0 + numerator / denominator;
        return std.math.acosh(arg);
    }

    pub fn hyperbolicComposition(
        self: *BolyaiHyperbolicEmbedding,
        concept_a: []const f32,
        concept_b: []const f32,
        allocator: std.mem.Allocator,
    ) ![]f32 {
        // Mobius addition a hiperbolikus térben
        // a ⊕ b = (a + b) / (1 + ⟨a,b⟩)

        var composition = try allocator.alloc(f32, concept_a.len);

        const dot_ab = dotProduct(concept_a, concept_b);
        const a_norm_sq = dotProduct(concept_a, concept_a);
        const b_norm_sq = dotProduct(concept_b, concept_b);

        const numerator_coeff = 1.0 + 2.0 * dot_ab + b_norm_sq;
        const denominator = 1.0 + 2.0 * dot_ab + a_norm_sq * b_norm_sq;

        for (0..concept_a.len) |i| {
            const num_a = concept_a[i] * (1.0 + 2.0 * dot_ab + b_norm_sq);
            const num_b = concept_b[i] * (1.0 - a_norm_sq);

            composition[i] = (num_a + num_b) / denominator;
        }

        return composition;
    }

    pub fn compositionGeneralization(
        self: *BolyaiHyperbolicEmbedding,
        primitive_concepts: []const []const f32,
        target_relation: Relation,
        allocator: std.mem.Allocator,
    ) ![]f32 {
        // Kompozíciós path a hiperbolikus térben
        var current = primitive_concepts[0];

        for (primitive_concepts[1..]) |concept| {
            const composed = try self.hyperbolicComposition(
                current,
                concept,
                allocator
            );
            current = composed;
        }

        // Relation-based adjustment a célhoz
        const adjusted = try self.adjustByRelation(
            current,
            target_relation,
            allocator
        );

        return adjusted;
    }

    fn adjustByRelation(
        self: *BolyaiHyperbolicEmbedding,
        embedding: []const f32,
        relation: Relation,
        allocator: std.mem.Allocator,
    ) ![]f32 {
        // Parallel transport a hiperbolikus térben
        var adjusted = try allocator.alloc(f32, embedding.len);

        const relation_vector = relation.directionVector();

        // Hiperbolikus exponential map
        const transported = try self.exponentialMap(
            embedding,
            relation_vector,
            allocator
        );

        return transported;
    }

    fn exponentialMap(
        self: *BolyaiHyperbolicEmbedding,
        base_point: []const f32,
        tangent_vector: []const f32,
        allocator: std.mem.Allocator,
    ) ![]f32 {
        // exp_p(v) a Poincaré ball-ban
        var result = try allocator.alloc(f32, base_point.len);

        const v_norm = euclideanNorm(tangent_vector);
        const p_norm_sq = dotProduct(base_point, base_point);
        const lambda_p = 2.0 / (1.0 - p_norm_sq);

        const tanh_factor = @tanh(lambda_p * v_norm / 2.0);

        // Mobius addition: p ⊕ (tanh(...) * v/||v||)
        var scaled_v = try allocator.alloc(f32, tangent_vector.len);
        defer allocator.free(scaled_v);

        for (tangent_vector, 0..) |v_i, i| {
            scaled_v[i] = (v_i / v_norm) * tanh_factor;
        }

        const composed = try self.hyperbolicComposition(
            base_point,
            scaled_v,
            allocator
        );

        return composed;
    }
};


