            allocator
        );
        results.hallucination_rate = halluc_score;
        std.debug.print("Hallucination Rate: {d:.2}%\n", .{halluc_score * 100});

        // 2. Catastrophic Forgetting Benchmark
        std.debug.print("\n=== Continual Learning Benchmark ===\n", .{});
        const forgetting_score = try runContinualLearningBenchmark(
            model,
            test_datasets.continual_tasks,
            allocator
        );
        results.forgetting_ratio = forgetting_score;
        std.debug.print("Forgetting Ratio: {d:.2}%\n", .{forgetting_score * 100});

        // 3. Long Context Reasoning
        std.debug.print("\n=== Long Context Benchmark ===\n", .{});
        const long_ctx_score = try runLongContextBenchmark(
            model,
            test_datasets.babilong,
            allocator
        );
        results.long_context_accuracy = long_ctx_score;
        std.debug.print("Long Context Accuracy: {d:.2}%\n", .{long_ctx_score * 100});

        // 4. Causal Reasoning
        std.debug.print("\n=== Causal Reasoning Benchmark ===\n", .{});
        const causal_score = try runCausalReasoningBenchmark(
            model,
            test_datasets.causal_tasks,
            allocator
        );
        results.causal_reasoning_score = causal_score;
        std.debug.print("Causal Reasoning Score: {d:.2}%\n", .{causal_score * 100});

        // 5. Explainability
        std.debug.print("\n=== Explainability Benchmark ===\n", .{});
        const explain_score = try runExplainabilityBenchmark(
            model,
            test_datasets.explanation_tasks,
            allocator
        );
        results.explainability_score = explain_score;
        std.debug.print("Explainability Score: {d:.1}/5.0\n", .{explain_score});

        // 6. Adversarial Robustness
        std.debug.print("\n=== Adversarial Robustness Benchmark ===\n", .{});
        const adv_score = try runAdversarialBenchmark(
            model,
            test_datasets.adversarial_attacks,
            allocator
        );
        results.adversarial_defense_rate = adv_score;
        std.debug.print("Defense Success Rate: {d:.2}%\n", .{adv_score * 100});

        // 7. Compositional Generalization
        std.debug.print("\n=== Compositional Generalization (SCAN) ===\n", .{});
        const comp_score = try runCompositionalBenchmark(
            model,
            test_datasets.scan_benchmark,
            allocator
        );
        results.compositional_gen_score = comp_score;
        std.debug.print("SCAN Accuracy: {d:.2}%\n", .{comp_score * 100});

        // 8. Uncertainty Calibration
        std.debug.print("\n=== Uncertainty Calibration ===\n", .{});
        const uce_score = try runCalibrationBenchmark(
            model,
            test_datasets.calibration_set,
            allocator
        );
        results.expected_calibration_error = uce_score;
        std.debug.print("Expected Calibration Error: {d:.4}\n", .{uce_score});

        // 9. ZK Verification Overhead
        std.debug.print("\n=== ZK Verification Benchmark ===\n", .{});
        const zk_overhead = try benchmarkZKOverhead(
            model,
            test_datasets.verification_samples,
            allocator
        );
        results.zk_proof_time_ms = zk_overhead;
        std.debug.print("ZK Proof Generation Time: {d:.1} ms\n", .{zk_overhead});

        return results;
    }

    fn runHallucinationBenchmark(
        model: *JaideNeuralV41,
        dataset: []const QAPair,
        allocator: std.mem.Allocator,
    ) !f32 {
        var hallucination_count: usize = 0;
        var total: usize = 0;

        for (dataset) |qa_pair| {
            const result = try model.forwardPass(qa_pair.question, allocator);

            // Ellenőrizzük a factual correctness-t
            const is_factual = try verifyFactualCorrectness(
                result,
                qa_pair.correct_answer,
            );

            // Neumann-Rédei truth value check
            const avg_truth = averageTruthValue(result.output_tokens);

            if (!is_factual or avg_truth < 0.7) {
                hallucination_count += 1;
            }

            total += 1;
        }

        return @as(f32, @floatFromInt(hallucination_count)) / 
               @as(f32, @floatFromInt(total));
    }

    fn runContinualLearningBenchmark(
        model: *JaideNeuralV41,
        tasks: []const ContinualTask,
        allocator: std.mem.Allocator,
    ) !f32 {
        var accuracies = std.ArrayList(f32).init(allocator);
        defer accuracies.deinit();

        // Baseline: initial task accuracy
        const initial_accuracy = try evaluateTask(model, tasks[0], allocator);
        try accuracies.append(initial_accuracy);

        // Sequential task learning
        for (tasks[1..]) |task| {
            // Train on new task
            _ = try model.trainWithConsolidation(task.training_data, allocator);

            // Evaluate on all previous tasks
            for (tasks[0..tasks.len]) |prev_task| {
                const acc = try evaluateTask(model, prev_task, allocator);
                try accuracies.append(acc);
            }
        }

        // Compute average forgetting
        const final_initial_acc = try evaluateTask(model, tasks[0], allocator);
        const forgetting = initial_accuracy - final_initial_acc;

        return @max(0.0, forgetting / initial_accuracy);
    }

    fn runLongContextBenchmark(
        model: *JaideNeuralV41,
        dataset: []const LongContextTask,
        allocator: std.mem.Allocator,
    ) !f32 {
        var correct: usize = 0;
        var total: usize = 0;

        for (dataset) |task| {
            // Task context length: 64K - 128K tokens
            const result = try model.forwardPass(task.long_context, allocator);

            // Multi-hop reasoning accuracy
            const is_correct = try verifyMultiHopAnswer(
                result,
                task.answer,
                task.reasoning_hops,
            );

            if (is_correct) {
                correct += 1;
            }
            total += 1;
        }

        return @as(f32, @floatFromInt(correct)) / @as(f32, @floatFromInt(total));
    }

    fn runCausalReasoningBenchmark(
        model: *JaideNeuralV41,
        dataset: []const CausalTask,
        allocator: std.mem.Allocator,
    ) !f32 {
        var correct: usize = 0;
        var total: usize = 0;

        for (dataset) |task| {
            const result = try model.forwardPass(task.scenario, allocator);

            // Verify causal chain
            const inferred_cause = try extractCausalChain(result.causal_chain);
            const is_correct = causesEqual(inferred_cause, task.true_cause);

            if (is_correct) {
                correct += 1;
            }
            total += 1;
        }

        return @as(f32, @floatFromInt(correct)) / @as(f32, @floatFromInt(total));
    }
};

const BenchmarkResults = struct {
    hallucination_rate: f32,
    forgetting_ratio: f32,
    long_context_accuracy: f32,
    causal_reasoning_score: f32,
    explainability_score: f32,
    adversarial_defense_rate: f32,
    compositional_gen_score: f32,
    expected_calibration_error: f32,
    zk_proof_time_ms: f32,

    pub fn compareWithSOTA(self: *const BenchmarkResults) void {
        std.debug.print("\n" ++ "=" ** 80 ++ "\n", .{});
        std.debug.print("JAIDE V41 VS SOTA COMPARISON\n", .{});
        std.debug.print("=" ** 80 ++ "\n\n", .{});

        const comparisons = [_]struct {
            metric: []const u8,
            jaide_v41: f32,
            sota_baseline: f32,
            unit: []const u8,
            lower_is_better: bool,
        }{
            .{ .metric = "Hallucination Rate", .jaide_v41 = self.hallucination_rate * 100, .sota_baseline = 23.0, .unit = "%", .lower_is_better = true },
            .{ .metric = "Forgetting Ratio", .jaide_v41 = self.forgetting_ratio * 100, .sota_baseline = 40.0, .unit = "%", .lower_is_better = true },
            .{ .metric = "Long Context Acc", .jaide_v41 = self.long_context_accuracy * 100, .sota_baseline = 52.5, .unit = "%", .lower_is_better = false },
            .{ .metric = "Causal Reasoning", .jaide_v41 = self.causal_reasoning_score * 100, .sota_baseline = 42.5, .unit = "%", .lower_is_better = false },
            .{ .metric = "Explainability", .jaide_v41 = self.explainability_score, .sota_baseline = 2.5, .unit = "/5", .lower_is_better = false },
            .{ .metric = "Adversarial Defense", .jaide_v41 = self.adversarial_defense_rate * 100, .sota_baseline = 20.0, .unit = "%", .lower_is_better = false },
            .{ .metric = "Compositional Gen", .jaide_v41 = self.compositional_gen_score * 100, .sota_baseline = 47.5, .unit = "%", .lower_is_better = false },
            .{ .metric = "Calibration (ECE)", .jaide_v41 = self.expected_calibration_error, .sota_baseline = 0.15, .unit = "", .lower_is_better = true },
        };

        for (comparisons) |comp| {
            const improvement = if (comp.lower_is_better)
                ((comp.sota_baseline - comp.jaide_v41) / comp.sota_baseline) * 100
            else
                ((comp.jaide_v41 - comp.sota_baseline) / comp.sota_baseline) * 100;

            std.debug.print("{s:<25} | Jaide v41: {d:>6.2}{s} | SOTA: {d:>6.2}{s} | Improvement: {d:>+6.1}%\n", 
                .{ comp.metric, comp.jaide_v41, comp.unit, comp.sota_baseline, comp.unit, improvement });
        }

        std.debug.print("\n" ++ "=" ** 80 ++ "\n", .{});
    }
};


